using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed.
            // EF Core 9 defaults to "$type" instead of "Discriminator".
            // Existing 500K documents use "Discriminator", and direct SQL
            // queries reference c.Discriminator, so preserve the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id format changed.
            // EF Core 9 no longer prepends the type name, so new ids would
            // be "123" instead of "Product|123". Existing documents still
            // use "Product|123". Restore the old format with HasIdProperty
            // mapping that includes the type prefix.
            entity.HasPartitionKey(p => p.Id);
        });

        // BREAKING CHANGE 3 — HasIndex is no longer supported.
        // The Cosmos provider now throws for HasIndex; removed above.
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Restore EF Core 8 id format: "EntityName|KeyValue"
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Cosmos.Conventions.IdFormatConvention());
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

