class CosmosQuery
{
    // BREAKING CHANGE 4 — Sync APIs removed.
    // The Cosmos provider no longer supports synchronous calls like
    // ToList(). All queries must use async equivalents.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still works because we preserved
        // "Discriminator" as the discriminator property name in OnModelCreating.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

